import cats.effect.IO
import grackle._
import grackle.Predicate._
import grackle.Query._
import grackle.QueryCompiler._
import grackle.Value._
import grackle.syntax._

object CurrencyData {
  case class Currency(code: String, exchangeRate: Double)
  val currencies = List(Currency("EUR", 1.12), Currency("GBP", 1.25))
}

object CurrencyMapping extends ValueMapping[IO] {
  import CurrencyData._

  val schema =
    schema"""
      type Query { fx(code: String): Currency }
      type Currency { code: String!; exchangeRate: Float! }
    """

  val QueryType = schema.ref("Query")
  val CurrencyType = schema.ref("Currency")

  val typeMappings =
    List(
      ValueObjectMapping[Unit](
        tpe = QueryType,
        fieldMappings = List(ValueField("fx", _ => currencies))
      ),
      ValueObjectMapping[Currency](
        tpe = CurrencyType,
        fieldMappings = List(
          ValueField("code", _.code),
          ValueField("exchangeRate", _.exchangeRate)
        )
      )
    )

  override val selectElaborator = SelectElaborator {
    case (QueryType, "fx", List(Binding("code", StringValue(code)))) =>
      Elab.transformChild(child =>
        Unique(Filter(Eql(CurrencyType / "code", Const(code)), child)))
  }
}

