object ComposedMapping extends ComposedMapping[IO] {
  val schema = schema"""
    type Query { country(code: String): Country; fx(code: String): Currency }
    type Country  { code: String!; name: String!; currency: Currency! }
    type Currency { code: String!; exchangeRate: Float! }
  """
  val QueryType    = schema.ref("Query")
  val CountryType  = schema.ref("Country")
  val CurrencyType = schema.ref("Currency")

  val typeMappings = List(
    ObjectMapping(tpe = QueryType, fieldMappings = List(
      Delegate("country", CountryMapping),
      Delegate("fx",      CurrencyMapping)
    )),
    ObjectMapping(tpe = CountryType, fieldMappings = List(
      Delegate("currency", CurrencyMapping, countryCurrencyJoin)
    ))
  )

  def countryCurrencyJoin(q: Query, c: Cursor): Result[Query] =
    (c.focus, q) match {
      case (c: CountryData.Country, Select("currency", _, child)) =>
        Select("fx",
          Unique(Filter(Eql(CurrencyType / "code", Const(c.currencyCode)), child))).success
      case _ => Result.internalError("Unexpected cursor focus type in countryCurrencyJoin")
    }
}

